import csv
import json

with open('inputs/eurostat/data/raw/real_sources/eurostat/urb_ctran.json', 'r') as f:
    data = json.load(f)

indicators = {}
for city in data['urb_ctran']:
    indicator_id = city['indicator_id']
    indicators[indicator_id] = city['indicator_name']

print('Indicators with mobility theme:')
for i in sorted(indicators.keys()):
    name = indicators[i]
    if 'mobility' in name.lower():
        print(f'{i}: {name}')
""}

